import java.util.Scanner;

public class Main {
    static final int N = 65;
    static final int MOD = 1000000007;
    static int m, len;
    static long n;
    static long[] v = new long[N];

    static class MatrixType {
        int[][] mat = new int[35][35];

        MatrixType() {
            for (int i = 0; i < 35; i++) {
                for (int j = 0; j < 35; j++) {
                    mat[i][j] = 0;
                }
            }
        }
    }

    static MatrixType mat_multiply(MatrixType a, MatrixType b) {
        MatrixType c = new MatrixType();
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= m; j++) {
                long sum = 0;
                for (int k = 0; k <= m; k++) {
                    sum += (long) a.mat[i][k] * b.mat[k][j];
                }
                c.mat[i][j] = (int) (sum % MOD);
            }
        }
        return c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        m = sc.nextInt();

        v[0] = n;
        len = 0;
        while (v[len] != 0) {
            v[len + 1] = v[len] / m;
            v[len] %= m;
            len++;
        }

        MatrixType[][] Tmat = new MatrixType[N][35];
        MatrixType[][] s1Arr = new MatrixType[N][35];
        MatrixType[][] s2Arr = new MatrixType[N][35];

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < 35; j++) {
                Tmat[i][j] = new MatrixType();
                s1Arr[i][j] = new MatrixType();
                s2Arr[i][j] = new MatrixType();
            }
        }

        for (int i = 0; i < len; i++) {
            if (i == 0) {
                for (int j = 0; j < m; j++) {
                    Tmat[i][j].mat[m][m] = 1;
                    for (int a = 0; a < m; a++) {
                        if (a != j) {
                            Tmat[i][j].mat[a][a] = 1;
                        } else {
                            for (int b = 0; b <= m; b++) {
                                Tmat[i][j].mat[a][b] = 1;
                            }
                        }
                    }
                }
            } else {
                for (int j = 0; j < m; j++) {
                    if (j == 0) {
                        s2Arr[i][0] = s2Arr[i - 1][0];
                        // Copying reference, but in Java, need to clone or assign new object
                        s2Arr[i][0] = copyMatrix(s2Arr[i - 1][0]);
                    } else {
                        s2Arr[i][j] = mat_multiply(s2Arr[i - 1][j], s1Arr[i - 1][j - 1]);
                    }
                }
            }
            s1Arr[i][0] = Tmat[i][0];
            for (int j = 1; j < m; j++) {
                s1Arr[i][j] = mat_multiply(s1Arr[i][j - 1], Tmat[i][j]);
            }
            s2Arr[i][m - 1] = Tmat[i][m - 1];
            for (int j = m - 2; j >= 0; j--) {
                s2Arr[i][j] = mat_multiply(Tmat[i][j], s2Arr[i][j + 1]);
            }
        }

        MatrixType matRes = new MatrixType();
        for (int i = 0; i <= m; i++) {
            matRes.mat[0][i] = 1;
        }

        int j = 0;
        for (int i = len - 1; i >= 0; i--) {
            long count = v[i];
            while (count-- > 0) {
                matRes = mat_multiply(matRes, Tmat[i][j]);
                j = (j + 1) % m;
            }
        }

        System.out.println(matRes.mat[0][m]);
        sc.close();
    }

    static MatrixType copyMatrix(MatrixType original) {
        MatrixType copy = new MatrixType();
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= m; j++) {
                copy.mat[i][j] = original.mat[i][j];
            }
        }
        return copy;
    }
}

